"""make_api.py - list what the scene kit offers: python3 make_api.py > API.md   (functions with their arguments, materials, modes)"""
import ast, re, os
NOTES = {'fr': 'seconds -> frame number (fractional)', 'fcurves_of': 'the f-curves of a datablock (Blender 5.3: through layers/strips/channelbag); used to inspect keys',
 'key': 'insert a keyframe at second t and set its interpolation (ip) and easing; a key on the same frame REPLACES the old key',
 'hidden_until': 'the object is invisible until t0', 'appear': 'appears by scaling up with a small overshoot (over), over dur seconds', 'vanish': 'shrinks and disappears',
 'grow': 'grows from its base along one axis between t0 and t1', 'show': 'hard show/hide (CONSTANT keys) between t0 and t1',
 'travel': 'moves through timed points: stops = [(t, (x, y, z)), ...]', 'key_input': 'animate the value of a material node socket',
 'new_mat': 'simple Principled material: colour, roughness, emission, specular, alpha', 'bsdf_of': 'the Principled node of a material', 'link': 'link an object into the scene, give it a material and a parent',
 'box': 'box from x, y, z bounds; origin = bottom | top | center (pivot for scale/rotation)', 'tube': 'tube through a list of points (a curve with bevel)',
 'extend': 'a pipe/tube draws itself from base to tip between t0 and t1', 'sphere': 'sphere (can be flattened with sx, sy, sz)',
 'cyl': 'cylinder or cone (r2) standing at loc; down=True hangs it downward', 'prism': 'prism from a profile in the XZ plane, extruded from y0 to y1',
 'patch': 'single-sided plane from an XZ profile (a stain, a thin layer) in front of the cut face', 'empty': 'empty object used as a parent or hinge',
 'text': '3D text (Inter Bold when available)', 'sign': 'a sign with text', 'screen_to_world': 'screen position (fractions) -> world point for a camera pose',
 'soil_material': 'soil layered by depth', 'grass_material': 'finely striped grass', 'gravel_material': 'gravel',
 'pose': 'frontal camera pose: x, distance, camera height, target height', 'push': 'a pose slightly closer than pose p (for a drift)', 'cam_key': 'camera + target key at second t',
 'hero_pose': 'orbit pose: azimuth (90 = straight on), elevation, distance, target; alias: orbit()'}
HERE = os.path.dirname(os.path.abspath(__file__)); out = ['# Scene kit API (generated by make_api.py; do not edit by hand)', '']
for fn, title in (('explainer_kit.py', 'explainer_kit.py - core (from video #1)'), ('scene_extras.py', 'scene_extras.py - extras (from video #2)')):
    src = open(os.path.join(HERE, fn), encoding='utf8').read(); lines = src.split('\n'); tree = ast.parse(src)
    out += [f'## {title}', '', '| Function | Description |', '|---|---|']
    for n in tree.body:
        if not isinstance(n, ast.FunctionDef) or n.name.startswith('_'): continue
        sig = re.sub(r'^def |:\s*$', '', lines[n.lineno - 1].split(':')[0] if lines[n.lineno - 1].rstrip().endswith(':') else re.match(r'def [^:]*\)', lines[n.lineno - 1]).group(0)[4:])
        doc = ast.get_docstring(n) or ''
        if not doc and n.lineno >= 2 and lines[n.lineno - 2].startswith('# ') and '====' not in lines[n.lineno - 2] and '----' not in lines[n.lineno - 2]: doc = lines[n.lineno - 2][2:]
        if not doc and '#' in lines[n.lineno - 1]: doc = lines[n.lineno - 1].split('#', 1)[1].strip()
        doc = doc or NOTES.get(n.name, '')
        out.append(f"| `{sig}` | {' '.join(doc.split()).replace('|', chr(92) + '|')} |")
    mats = sorted(set(re.findall(r'^(M_[A-Za-z0-9_]+) = ', src, re.M)) | set(re.findall(r'; (M_[A-Za-z0-9_]+) = ', src)))
    out += ['', 'Materials: ' + ', '.join(f'`{m}`' for m in mats), '']
out += ['## World objects and modes', '', '- World: camera `cam` (36 mm lens), sun `sun` / `sun_d` (energy and colour can be keyframed), sky `sky` (colour ramp), `sc` = the scene.',
        '- Time: `FPS`, `OFFSET`, `DUR`, `LAST` (last frame), `WORDS` from `kitjob.py`; `T(id, word, nth, end)` gives seconds in the video; `fr(t)` turns seconds into a frame number.',
        '- Modes (first argument of a scene script): `still <rx> <ry> <spp> <dir> <seconds...>`, `anim <rx> <ry> <spp> <dir> <first> <last> [step]`, `list <rx> <ry> <spp> <dir> <file of frame numbers>`, `blend <rx> <ry> <spp> <out.blend>`, `none` (only builds the scene).',
        '- Environment variables: `KIT_DEVICE=CPU|GPU`, `KIT_FMT=PNG|JPEG`, `KIT_PERSIST=0|1` (leave it at 0), `SEPTIC_FONT=<font for 3D text>`.', '']
print('\n'.join(out))
